INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Jahitan obras tidak terbentuk dengan benar', 'Jahitan stitch type 514 tidak rapat, tidak seimbang, atau bentuk rantai benang tidak sesuai.', 'Tegangan benang tidak seimbang, jalur benang salah, atau penyetelan looper dan jarum tidak tepat.', 'Periksa kembali jalur pemasangan benang, sesuaikan tegangan benang secara bertahap, dan periksa penyetelan jarum serta looper.', 'Matikan mesin dan lepaskan pedal sebelum melakukan penyetelan atau pemeriksaan pada area jarum dan looper.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Benang salah satu jarum sering putus', 'Benang pada salah satu jarum putus berulang saat mesin berjalan.', 'Jarum bengkok atau tumpul, pemasangan jarum tidak tepat, tegangan benang terlalu tinggi, atau jalur benang terganggu.', 'Ganti jarum dengan DC×27 yang sesuai, pastikan posisi jarum benar, periksa jalur benang, lalu sesuaikan tegangan benang.', 'Matikan mesin sebelum mengganti jarum dan jangan menyentuh jarum saat mesin sedang beroperasi.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Benang looper sering putus', 'Benang looper putus saat proses obras atau jahitan tidak dapat terbentuk sempurna.', 'Jalur benang looper salah, tegangan terlalu tinggi, benang tersangkut, atau looper tidak tersetel dengan benar.', 'Periksa seluruh jalur benang looper, lepaskan benang yang tersangkut, sesuaikan tegangan, dan periksa posisi looper.', 'Matikan mesin sebelum membuka penutup atau melakukan pemeriksaan pada area looper.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Jahitan salah satu jalur loncat atau tidak terbentuk', 'Salah satu jalur jahitan tidak terbentuk secara konsisten dan terdapat bagian jahitan yang loncat.', 'Jarum tidak sesuai atau tumpul, posisi jarum kurang tepat, timing jarum-looper tidak sesuai, atau tekanan material tidak stabil.', 'Periksa dan ganti jarum DC×27 bila perlu, pastikan pemasangan benar, lalu periksa penyetelan jarum dan looper.', 'Matikan mesin sebelum memeriksa jarum, looper, atau timing mekanisme jahitan.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Tepi kain mengerut atau bergelombang', 'Tepi kain setelah diobras tampak mengerut, tertarik, atau bergelombang.', 'Differential feed tidak sesuai dengan karakter bahan, tekanan sepatu terlalu tinggi, atau tegangan benang tidak seimbang.', 'Sesuaikan differential feed secara bertahap, atur tekanan sepatu sesuai bahan, dan seimbangkan tegangan benang.', 'Lakukan penyetelan saat mesin berhenti dan gunakan potongan bahan uji sebelum produksi.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Lebar obras tidak sesuai', 'Lebar jahitan obras tidak sesuai dengan ukuran yang dibutuhkan, misalnya pilihan 3,2 mm, 4,0 mm, atau 4,8 mm.', 'Komponen pembentuk lebar obras tidak sesuai, penyetelan mesin berubah, atau posisi kain tidak stabil.', 'Periksa penyetelan lebar obras, gunakan ukuran yang sesuai kebutuhan produksi, dan pastikan kain diarahkan dengan stabil.', 'Matikan mesin sebelum mengubah komponen atau penyetelan di area pembentukan jahitan.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Salah satu jarum patah atau posisi jarum tidak normal', 'Salah satu dari dua jarum patah, bengkok, atau terlihat tidak sejajar saat mesin beroperasi.', 'Jarum rusak, pemasangan tidak tepat, jarum menyentuh looper atau komponen lain, atau bahan terdorong tidak stabil.', 'Matikan mesin, ganti jarum DC×27 yang sesuai, pastikan kedua jarum terpasang pada posisi yang benar, dan periksa kemungkinan kontak dengan looper.', 'Jangan menjalankan mesin dengan jarum bengkok atau patah. Pastikan mesin benar-benar berhenti sebelum mengganti jarum.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (27, 'Pelumasan atau gerakan mesin tidak normal', 'Gerakan mesin terasa berat, suara mekanis meningkat, atau area kerja menunjukkan tanda pelumasan tidak normal.', 'Level atau kondisi oli tidak sesuai, sistem pelumasan otomatis terganggu, atau terdapat kotoran pada area mekanisme.', 'Periksa sistem pelumasan otomatis dan kondisi oli sesuai petunjuk mesin, bersihkan area mekanisme yang dapat dijangkau, dan hentikan mesin bila suara abnormal tetap muncul.', 'Matikan mesin dan putuskan sumber listrik sebelum pemeriksaan mekanis. Jangan menjalankan mesin bila terdapat suara atau gerakan yang berpotensi membahayakan.', 'Panduan troubleshooting umum mesin overlock JUKI MO-6900S Series');
